xml.Script:
        Colors[2] := 'DD0000'; // Red   
        Colors[1] := 'FF7700'; // Orange
        Colors[4] := '8800CC'; // Purple
        Colors[0] := 'AAAAAA'; // Gray  
        Colors[3] := '009900'; // Green 
        Colors[5] := '0022EE'; // Blue  
        Colors[6] := '222222'; // Black 
        Colors[7] := 'FFFF00'; // Yellow

        sAngle := Pi * 2 / 3;
        for i := 0 to 2 do begin
            ax[i] := sin(sAngle * i);
            ay[i] := cos(sAngle * i);
        end;

        R := 0.55;
        H := R * 0.8;

        N := 60; // nuber of sides of cylinders, must be divisible by 6
        N1 := 4; // must be even
        N2 := N div 3 - N1;

        D := H / 3;
        RC := D * 1.59; // must be > D * sqrt(2) 
        D1 := R * cos(Pi / N * N2);
        D2 := sqrt(R^2 - Rc^2) * 0.999;

        for i := 0 to N - 1 do begin
            A := 2 * Pi / N * i;
            x[i] := R * cos(A);
            y[i] := R * sin(A);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
